X = {}

X["iptv-error-messages-explained"] = [
 ("Reading an error properly",["Write down the exact wording and any code number. The same words can mean different things in different apps, but a code helps support find the cause quickly. Take a photo of the screen with your phone if you cannot copy the text.","Notice when it appears. An error that shows up only at start suggests a sign-in or network problem. One that appears during playback suggests a stream or connection problem."]),
 ("What not to do",["Do not repeatedly reinstall the app before you have checked the basics. Do not paste your password into a public group to ask for help."])]

X["iptv-wont-sign-in"] = [
 ("A worked example",["A customer typed their password and the app said invalid login. They copied and pasted the details from the message, and it worked. The original typing had a lowercase l in place of a capital I. This is extremely common, so pasting is the first thing to try.","Another customer found the date on their stick was a week behind after a power cut. Setting automatic time fixed the problem at once."])]

X["iptv-app-keeps-restarting"] = [
 ("Telling memory from heat",["If the app closes at random moments, even when you only browse, memory is the likely cause. If it runs well for the first half hour and then fails, heat or a slow memory leak in the app is more likely.","Feel the device after it has run for an hour. If it is very hot, give it airflow and see whether the problem eases. If the app only crashes on one very large category, try removing that category."])]

X["iptv-picture-pixelated"] = [
 ("Isolating the cause in ten minutes",["Play one channel on Wi-Fi for five minutes and note what you see. Then plug in a cable, if possible, and compare. Then try the same channel on a different device such as a phone. If all three look blocky, the stream is the cause. If only one looks blocky, the weak link is that device or connection.","Record your findings. They make support much faster."])]

X["iptv-works-on-phone-not-tv"] = [
 ("A useful comparison",["Put the phone and the TV side by side, both playing the same channel on the same Wi-Fi. If the phone is fine and the TV is not, move the TV closer to the router or use a cable. If both work on a cable but the TV fails on Wi-Fi, the TV's wireless hardware is the weakness.","Also check that the TV is not connected to a guest network or a different band that restricts traffic."])]

X["router-restart-vs-factory-reset"] = [
 ("A safe habit",["Restart the router occasionally, for example once a month, when no one is watching. Do not do it during a match. A scheduled restart, if your router offers one, can be set for the small hours.","Before any reset, take a photo of the label with the default Wi-Fi name and password and write down your provider's login details if you have changed them."])]

X["iptv-after-changing-broadband"] = [
 ("Common surprises",[("ul",["The new router is in a different place and the signal in the TV room is weaker.","The Wi-Fi name is the same but the password is different.","The new line is slower in the evening.","An old range extender is still connected to the old network."])]),
 ("A calm approach",["Test one device on a cable first. If that works well, the problem is Wi-Fi coverage. If not, speak to your new provider about the line."])]

X["dns-settings-and-streaming"] = [
 ("What DNS will not fix",["DNS will not repair a weak Wi-Fi signal, a congested line, or a stream that is down. If your picture stutters while playing, DNS is almost never the cause. Look at {post:improve-wifi-for-streaming} instead.","If a lookup problem is genuine, you will often see slow first loads and messages about not finding the server. In that case a test of another DNS setting on one device is reasonable."])]

X["football-season-iptv-checklist"] = [
 ("The weekend routine",["On match day, restart the device in the morning, check the guide for the kick-off time, and close other apps. Ask other people at home to avoid heavy downloads. Put your phone on silent for score alerts if you are watching with a slight delay.","If the picture falters, wait ten seconds before changing anything, and then try the same channel again before restarting the app."]),
 ("Keep a log",["Note which matches caused trouble and when. Patterns, for example every Saturday at three, help you and support find the cause."])]

X["combat-sports-streaming-prep"] = [
 ("Late night extras",["Fight nights often run past midnight. Make sure your device will not go to sleep and that automatic updates will not restart it during the event. Many streaming devices install updates overnight, so check the settings earlier in the day.","Charge any backup phone or tablet, in case you need to switch."])]

X["f1-weekend-streaming-tips"] = [
 ("Pace yourself over the weekend",["Practice sessions are a good, low-pressure test of your setup. Use them to check sound, the guide and your connection ahead of the race. If something is wrong, you will have time to fix it.","Remember that onboard and alternative camera feeds may not be part of every channel, so do not assume features without checking."])]

X["cricket-and-rugby-streaming-tips"] = [
 ("Cricket specific",["A five day match gives you plenty of time to settle a problem, but also wears on a device. Restart at the start of each day and watch the temperature of the stick or box.","For short formats the action is concentrated, so treat them like any big live event and test beforehand."]),
 ("Rugby specific",["Fixtures have fixed kick-off times and often draw a lot of simultaneous viewers. Be set up a quarter of an hour before kick-off, with the correct channel already open."])]

X["reduce-delay-in-live-sport-streams"] = [
 ("A practical spoiler plan",["If you want to avoid hearing the result early, put your phone away or switch off notifications for sports apps. Tell the people you are watching with not to check their phones. Even a ten second delay is long enough for a goal alert to arrive before the picture.","If you watch with a group, agree to use the same device so everyone shares the same delay."])]

X["hls-streaming-explained"] = [
 ("Why this matters when you test",["When you test a service, look at how quickly a channel starts and whether the picture quality changes. A channel that starts slowly but plays steadily is a different case from one that starts quickly and then stutters. The first suggests a bigger buffer or a slower start, the second suggests your connection is not keeping up.","You do not need to know the technical details, only that short pieces are being fetched all the time."])]

X["bitrate-and-resolution-explained"] = [
 ("A simple comparison",["Imagine two pictures of the same size. One is a clean sharp photograph, the other the same photograph squeezed until it blurs. They have the same resolution but very different bitrates. On a screen, the squeezed one shows blocky patches in dark scenes and fast motion.","This is why a 1080p stream can sometimes look worse than a lower resolution one with more data."])]

X["latency-in-live-streaming"] = [
 ("How to measure it roughly",["Open a live clock website or a radio clock, and watch a channel showing a clock or a countdown. Compare them. You will see how far behind real time your stream is. Do the test a few times, because the delay can change from one session to another.","If the gap grows over time, the player may be slowly falling behind. Restarting the app brings you back to live."])]

X["catch-up-tv-explained"] = [
 ("Why it is not guaranteed",["Catch-up needs the service to store programmes, and storage costs money, so it is often limited to some channels and some time windows. It also depends on the schedule data matching correctly.","If a programme you expect is missing, check whether it has actually aired yet and whether the window has passed."])]

X["multicast-vs-unicast-iptv"] = [
 ("A home example",["Suppose three screens in your house watch three different channels. With unicast, three separate streams travel through your connection. Even if two people watch the same channel at the same time, each device usually gets its own copy. This is why the number of screens, not the number of channels, drives your bandwidth.","Telecom operators who deliver television inside their own network can use multicast to share one stream among many boxes, which is a different system from the internet based services most people use at home."])]

X["how-to-renew-iptv-safely"] = [
 ("Warning signs at renewal",[("ul",["A message from a new number claiming to be us.","A link to a payment page you do not recognise.","Pressure to pay within minutes.","A request for card numbers or passwords."])]),
 ("What we do",["We confirm renewals through the same WhatsApp conversation or the contact details on this site, and we confirm the plan and the total before you pay."])]

X["upgrade-your-iptv-plan"] = [
 ("An example",["Suppose you started on a plan for two screens and a relative moved in. Rather than guessing, count how many screens run at once in the busiest evening and ask what that needs. If an upgrade is only needed for a few weeks, ask whether there is a sensible alternative.","Upgrading should never be rushed. Ask for the figures, check them against the {plans}, and take your time."])]

X["iptv-payment-methods-explained"] = [
 ("Choosing for your situation",["If you want a familiar route with dispute options, PayPal is often the choice. If you already hold crypto and know how to check a payment, Binance Pay is quick. If you are paying from another country and want to see the exchange rate in advance, Wise can be clear and cheap.","Whatever you pick, pay the exact amount we confirm and send us the receipt."])]

X["iptv-refund-expectations"] = [
 ("What strengthens a request",["Clear evidence helps: dates, screenshots, the steps you tried and how long the problem lasted. If the problem is on your side, such as a device that cannot run the app, we will say so. If it is on ours, we want to know.","Responding quickly matters, because many policies have a time limit. Read ours in full."])]

X["iptv-vs-pay-per-view"] = [
 ("A worked example",["Suppose you watch six major events a year and each costs a set fee. Add the six fees together and compare the total with one year of a subscription. If the subscription total is lower and the events are included, the subscription wins. If the events are only available as separate purchases, the answer changes.","Do the same sum before every big season, because prices and arrangements change."])]
